CREATE TABLE IF NOT EXISTS document_signature_envelopes(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,document_id TEXT NOT NULL,provider_mode TEXT NOT NULL,status TEXT NOT NULL,original_artifact_reference TEXT NOT NULL,signed_artifact_reference TEXT NOT NULL,completion_certificate_reference TEXT NOT NULL,signer_authentication_json TEXT NOT NULL,timestamps_json TEXT NOT NULL,custody_chain_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,completed_at TEXT);
CREATE TABLE IF NOT EXISTS document_destruction_requests(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,document_id TEXT NOT NULL,status TEXT NOT NULL,requested_by TEXT NOT NULL,requested_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,reason TEXT NOT NULL,legal_hold_checked INTEGER NOT NULL,certificate_reference TEXT,CHECK(approved_by IS NULL OR approved_by<>requested_by));
CREATE TABLE IF NOT EXISTS document_retention_overrides(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,document_id TEXT NOT NULL,policy_retention_until TEXT NOT NULL,override_retention_until TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(trim(reason))>0),authorized_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_custody_certification_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,status TEXT NOT NULL,provider_mode TEXT NOT NULL,document_reference TEXT NOT NULL,ledger_json TEXT NOT NULL,terminal_hash TEXT NOT NULL,negative_controls_json TEXT NOT NULL,production_enabled INTEGER NOT NULL DEFAULT 0,real_document_destroyed INTEGER NOT NULL DEFAULT 0,real_signature_sent INTEGER NOT NULL DEFAULT 0,executed_by TEXT NOT NULL,executed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS document_signature_scope_idx ON document_signature_envelopes(organization_id,property_id,document_id,created_at);
CREATE INDEX IF NOT EXISTS document_destruction_queue_idx ON document_destruction_requests(organization_id,property_id,status,requested_at);
CREATE INDEX IF NOT EXISTS document_retention_override_scope_idx ON document_retention_overrides(organization_id,property_id,document_id,created_at);
CREATE INDEX IF NOT EXISTS document_custody_certification_idx ON document_custody_certification_runs(organization_id,property_id,executed_at);
